	default Color freshColor()
	{
		return new Color(0, 255, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "expiredColor",
		name = "Expiring Color",
		description = "Circle color when a spot is about to move",
		position = 1,
		section = colorSection
	)
	default Color expiredColor()
	{
